import{_ as r,o as e,c as o,a2 as a}from"./chunks/framework.BZO4qERu.js";const u=JSON.parse('{"title":"应用市场（Supermarket）","description":"","frontmatter":{},"headers":[],"relativePath":"zh/guides/supermarket.md","filePath":"zh/guides/supermarket.md","lastUpdated":1792323081000}'),s={name:"zh/guides/supermarket.md"};function n(l,t,i,d,h,g){return e(),o("div",null,[...t[0]||(t[0]=[a('<h1 id="应用市场-supermarket" tabindex="-1">应用市场（Supermarket） <a class="header-anchor" href="#应用市场-supermarket" aria-label="Permalink to &quot;应用市场（Supermarket）&quot;">​</a></h1><p>应用市场是 Memoh 内置的应用目录。这里的<strong>应用（App）<strong>是一个打包好的能力单元：一个 App 里可以带若干 <strong>Skill</strong>（可复用的流程说明）、若干</strong>依赖</strong>（要装进工作区的工具），以及若干<strong>连接器</strong>（GitHub、Notion 这类第三方服务的绑定）。装的是整个 App，不用再分别找 Skill 或连接器。</p><p>在客户端侧边栏打开 <strong>应用市场</strong>：应用按分类陈列，可搜索、按标签筛选。点进详情页能看到应用的说明、组件构成（多少个 Skill、依赖、连接器）、作者、版本、来源 Registry 和链接。</p><hr><h2 id="安装一个应用" tabindex="-1">安装一个应用 <a class="header-anchor" href="#安装一个应用" aria-label="Permalink to &quot;安装一个应用&quot;">​</a></h2><ol><li>在 <strong>应用市场</strong> 挑一个应用，进入详情页。</li><li>点 <strong>安装到 Bot</strong>，选择目标 Bot。</li><li>应用声明了环境变量的，先把需要的值填好。</li><li>确认安装。</li></ol><p>安装和更新需要该 Bot 的工作区处于运行状态：Skill 会写进工作区，依赖装进工作区，连接器建立绑定。安装过程有进度展示，中断了可以<strong>继续安装</strong>或<strong>恢复安装</strong>。</p><hr><h2 id="装好之后-bot-的「应用」标签" tabindex="-1">装好之后：Bot 的「应用」标签 <a class="header-anchor" href="#装好之后-bot-的「应用」标签" aria-label="Permalink to &quot;装好之后：Bot 的「应用」标签&quot;">​</a></h2><p>Bot 详情页的 <strong>应用</strong> 标签列出已安装的 App，按组件展示状态：</p><table tabindex="0"><thead><tr><th>组件</th><th>去向</th></tr></thead><tbody><tr><td><strong>Skill</strong></td><td>写进工作区的受管目录 <code>/data/skills/&lt;registry&gt;/&lt;app&gt;/</code>，由应用管理——更新、卸载时一起处理，别手动改（见<a href="./skills.html">技能</a>）</td></tr><tr><td><strong>依赖</strong></td><td>装进该 Bot 的工作区，并与同工作区里需要它们的其他应用共享</td></tr><tr><td><strong>连接器</strong></td><td>标注<strong>需要授权</strong>、<strong>可选</strong>或<strong>所有工作区共享</strong>；点<strong>去授权</strong>完成 OAuth 或填入 API Key（见<a href="./../self-hosted/connectors.html">连接器</a>）</td></tr></tbody></table><p>常用操作：<strong>检查更新</strong>、<strong>更新</strong>、<strong>卸载</strong>。部分组件失败或还没授权时，应用会标成&quot;需要处理&quot;，点开组件列表补齐即可。</p><hr><h2 id="市场内容从哪来" tabindex="-1">市场内容从哪来 <a class="header-anchor" href="#市场内容从哪来" aria-label="Permalink to &quot;市场内容从哪来&quot;">​</a></h2><p>应用市场的内容来自上游 Registry，默认是 <code>supermarket.memoh.ai</code>。自部署实例可以把 <code>supermarket.base_url</code> 指向其它可信目录，见 <a href="./../self-hosted/docker.html">Server Deploy</a> 的配置参考。</p><hr><h2 id="贡献" tabindex="-1">贡献 <a class="header-anchor" href="#贡献" aria-label="Permalink to &quot;贡献&quot;">​</a></h2><p>新的应用可提交到：</p><ul><li><a href="https://github.com/felinics/supermarket" target="_blank" rel="noreferrer">felinics/supermarket</a></li></ul>',19)])])}const c=r(s,[["render",n]]);export{u as __pageData,c as default};
